document.addEventListener("DOMContentLoaded",function(){var width=0;var height=0;var widthCookie=util.getCookie(COOKIE_DISPLAY_WIDTH);if(widthCookie&&widthCookie!==""){width=parseInt(widthCookie,10)}var heightCookie=util.getCookie(COOKIE_DISPLAY_HEIGHT);if(heightCookie&&heightCookie!==""){height=parseInt(heightCookie,10)}if(width>0&&height>0){width+=(window.outerWidth-window.innerWidth);height+=(window.outerHeight-window.innerHeight);window.resizeTo(width,height)}});var onloadOrig=window.onload;window.onload=function(){if(typeof onloadOrig==="function"){onloadOrig()}if(document.getElementById("checkFailFlg").value=="1"){window.alert("エラーが発生しました。\n申し訳ありませんが、再度視聴ボタンを押下してください。");window.close()}};